def minimumIncompatibility(nums: list[int], k: int) -> int:
    from collections import Counter
    counts = Counter(nums)
    if any(c > k for c in counts.values()): return -1
    n = len(nums)
    sz = n // k
    if sz == 1: return 0
    valid_subsets = {}
    for mask in range(1 << n):
        if bin(mask).count('1') == sz:
            elements = [nums[i] for i in range(n) if (mask & (1 << i))]
            if len(set(elements)) == sz:
                valid_subsets[mask] = max(elements) - min(elements)
    dp = {0: 0}
    for mask in range(1 << n):
        if mask not in dp: continue
        first_unset = 0
        while first_unset < n and (mask & (1 << first_unset)):
            first_unset += 1
        if first_unset == n: continue
        for submask, cost in valid_subsets.items():
            if (submask & (1 << first_unset)) and (mask & submask) == 0:
                nxt = mask | submask
                if nxt not in dp or dp[mask] + cost < dp[nxt]:
                    dp[nxt] = dp[mask] + cost
    target = (1 << n) - 1
    return dp.get(target, -1)

